{
  "contract": "KatRoyalties",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "spin",
      "withdraw"
    ],
    "justification": "Both 'spin' and 'withdraw' touch the storage variables exposed by 'withdraw'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "spin"
    ],
    "nesting_bound": {
      "spin": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "before_withdraw",
      "to_marker": "after_withdraw_entry"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_withdraw_call",
      "to_marker": "after_withdraw_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_withdraw_call",
      "to_marker": "after_withdraw"
    },
    "linearization_point": "at_withdraw_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount in-flight during withdraw",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_balances == winnerFunds + inFlight",
    "stable_formula": "_sum_balances == winnerFunds",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_balances == winnerFunds",
    "rule": "exposure_invariant_ensures_target_property"
  }
}
